let page='',tripFilter='Todos',query='',ledgerFilter='Todos',calMonth=9,calYear=2026,selectedDate='2026-10-28',draft={origin:'',destination:'',stops:[],date:'2026-10-28',time:'09:00',category:'passageiros',people:1,weight:'',cargo:'',cost:'',note:'',contact:'',phone:''},modalTrip=null,lastFocus=null;
