function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Não foi possível salvar neste navegador. Os dados duram apenas nesta sessão.')}}
const reserved=()=>state.trips.filter(t=>t.status==='Agendada').reduce((s,t)=>s+t.price,0);
const accounting=()=>state.credit-state.spent;
const available=()=>accounting()-reserved();
const dateObj=d=>new Date(d+'T12:00:00');
const dateLabel=d=>dateObj(d).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.','');
const weekday=d=>dateObj(d).toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','');
const longDate=d=>dateObj(d).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'});
const idLabel=id=>'#'+String(id).padStart(4,'0');
function badge(status){return `<span class="badge ${status==='Orçamento'?'amber':status==='Solicitada'||status==='Em andamento'?'blue':status==='Cancelada'?'gray':''}">${status==='Orçamento'?'Aguardando aprovação':esc(status)}</span>`}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function navigate(target){if(location.hash==='#'+target)render();else location.hash=target}
const navItems=[['solicitar','pin','Solicitar viagem'],['inicio','home','Visão geral'],['corridas','route','Minhas corridas'],['agenda','calendar','Agenda'],['carteira','wallet','Carteira'],['locais','pin','Locais salvos']];
function shell(){return `<aside class="sidebar"><a href="#solicitar" class="brand" aria-label="IVO Transportes início"><span class="wordmark">IVO</span><span class="brand-sub">TRANSPORTES<br>PARA EMPRESAS</span></a><div class="company-switch"><div class="company-symbol">UM</div><div class="grow"><strong>Umi San</strong><small>Conta empresarial</small></div>${icon('shield',13)}</div><div class="nav-label">SEU ESPAÇO</div><nav class="nav" aria-label="Navegação principal"><i class="nav-marker" aria-hidden="true"></i>${navItems.map(([id,ico,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${id==='corridas'?`<span class="nav-badge">${state.trips.filter(t=>['Solicitada','Orçamento','Agendada','Em andamento'].includes(t.status)).length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><button data-action="help">${icon('help')}<span>Conte com a IVO</span></button><p>Um caminho mais simples.<br>Uma pessoa do outro lado.</p></div><div class="side-user row"><div class="avatar">DM</div><div class="user-text grow"><strong>Djully Maria</strong><small>Administradora</small></div></div></div></aside><div class="shell"><header class="topbar"><div class="crumb">Área do cliente ${icon('chevron',11)} <strong>${pageTitle()}</strong></div><a href="#solicitar" class="mobile-brand"><span class="wordmark">IVO</span><span class="small">Umi San</span></a><div class="top-actions"><span class="top-date">Terça-feira, 27 de outubro</span><button class="demo-btn" data-action="demo"><i></i>Protótipo</button><button class="icon-btn notice-icon" data-action="notifications" aria-label="Notificações">${icon('bell',17)}</button><div class="avatar" title="Perfil de demonstração">DM</div></div></header><main id="content" class="main" tabindex="-1">${content()}<footer class="footer"><span>IVO Transportes <span>·</span> Cuidamos do caminho.</span><span>${icon('shield',11)} Ambiente de demonstração · dados fictícios</span></footer></main></div><nav class="bottom-nav" aria-label="Navegação móvel">${[['solicitar','pin','Viajar'],['corridas','route','Corridas'],['agenda','calendar','Agenda'],['carteira','wallet','Carteira'],['inicio','home','Resumo']].map(([id,ico,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ico,20)}<span>${label}</span></a>`).join('')}</nav>`}
function pageTitle(){return {inicio:'Visão geral',corridas:'Minhas corridas',solicitar:'Solicitar transporte',agenda:'Agenda',carteira:'Carteira',locais:'Locais salvos',ajuda:'Ajuda'}[page]||'Visão geral'}
function header(title,sub,button=true){return `<div class="page-head between"><div><h1>${title}</h1><p>${sub}</p></div>${button?`<a class="btn" href="#solicitar" aria-label="Solicitar transporte">${icon('plus',16)} Solicitar transporte</a>`:''}</div>`}
function art(){return `<svg class="hero-art" viewBox="0 0 350 280" fill="none" aria-hidden="true"><g stroke="#49636c" stroke-width="1" opacity=".45"><path d="m10 190 140-75 180 91M0 223l150-79 180 92M80 0l160 85-80 44M167 0l155 82-78 44M180 130 70 190l110 59 108-59-108-60Z"/><path d="M45 87v55l50 27 56-30V82L95 56 45 87Z"/><path d="m45 87 50 26 56-31m-56 31v56M60 95V77l33-17m17 35V73M65 104v42m15-34v42m31-47v43m17-53v43"/><path d="m223 95 46-25 48 25v66l-48 25-46-26V95Zm0 0 46 25 48-25m-48 25v66m-34-82v41m17-32v41m31-33v40m18-50v41"/><path d="m101 233 28 15m-2-31 28 15m-2-31 28 15m-2-31 28 15"/></g><path d="M84 209 155 170Q170 163 182 170l37 19q10 6 20-1l44-24" stroke="#f68347" stroke-width="3" stroke-linecap="round" stroke-dasharray="5 7"/><circle cx="83" cy="209" r="7" fill="#fa8b52"/><circle cx="83" cy="209" r="14" stroke="#fa8b52" opacity=".3"/><g transform="translate(162 117)"><path d="m0 21 22-12 42 22-22 12L0 21Z" fill="#dce4dc"/><path d="m0 21 1 14 41 23V43L0 21Z" fill="#9cafab"/><path d="m42 43 22-12v15L42 58V43Z" fill="#eef1e8"/><path d="m9 20 12-18 23 12 10 20-12 7L9 20Z" fill="#d1dcd6"/><path d="m21 5 21 11 5 12-31-17 5-6Z" fill="#375565"/><path d="m12 19 3-7 13 7v10L12 19Zm18 11V20l12 7 5 12-17-9Z" fill="#375565"/><ellipse cx="13" cy="38" rx="5" ry="7" fill="#102d3d" transform="rotate(-18 13 38)"/><ellipse cx="49" cy="48" rx="5" ry="7" fill="#102d3d" transform="rotate(-18 49 48)"/><path d="m2 25 5 3m49 10 5-3" stroke="#fff" stroke-width="2"/></g><path d="M284 115c-12 0-21 9-21 21 0 16 21 33 21 33s21-17 21-33c0-12-9-21-21-21Z" fill="#f0793b"/><circle cx="284" cy="135" r="7" fill="#102d3d"/><path d="m110 201 6-3m185-1 9-5" stroke="#49636c"/><circle cx="214" cy="72" r="3" fill="#b9c8b7"/></svg>`}
function mapGraphic(){return `<div class="route-map"><svg viewBox="0 0 400 220" preserveAspectRatio="xMidYMid slice" aria-label="Ilustração esquemática do trajeto"><rect width="400" height="220" fill="#e9eee2"/><path d="M310-20c-50 58-21 79-64 104-54 32-47 56-4 89 19 16 25 38 16 64h150V-20Z" fill="#c7dce0"/><g stroke="#fff" stroke-width="10" fill="none"><path d="M-15 58 212 188M28-10l202 233M-12 157 230-10M16 216 262 34M155-8 48 233M238-8 139 222M-4 105l300 11"/></g><g stroke="#cdd5c6" stroke-width="1" fill="none"><path d="m0 58 212 130M28-10l202 233M-12 157 230-10M16 216 262 34M155-8 48 233M238-8 139 222M-4 105l300 11"/></g><path d="m75 150 59-43 75 4 42-30" stroke="#ed6a33" stroke-width="4" stroke-linecap="round" fill="none"/><circle cx="75" cy="150" r="8" fill="#102d3d" stroke="#fff" stroke-width="3"/><path d="M252 60c-7 0-12 5-12 12 0 9 12 20 12 20s12-11 12-20c0-7-5-12-12-12Z" fill="#ed6a33"/><circle cx="252" cy="72" r="3" fill="#fff"/><rect x="35" y="163" width="78" height="22" rx="4" fill="#fff"/><text x="74" y="178" text-anchor="middle" fill="#536b5c" font-size="9" font-family="sans-serif">ORIGEM</text><rect x="221" y="33" width="64" height="20" rx="4" fill="#fff"/><text x="253" y="47" text-anchor="middle" fill="#536b5c" font-size="9" font-family="sans-serif">DESTINO</text></svg><div class="map-label">TRAJETO ILUSTRATIVO · NÃO É NAVEGAÇÃO</div></div>`}
function dateSquare(d){return `<div class="date-square"><small>${dateObj(d).toLocaleDateString('pt-BR',{month:'short'}).replace('.','').toUpperCase()}</small><strong>${d.slice(-2)}</strong></div>`}
function routeBlock(t){return `<div class="trip-route"><div class="route-line"><i></i><b></b><i></i></div><div><div class="address"><strong>${esc(t.origin)}</strong><small>Origem${t.stops?.length?' · '+t.stops.length+' parada(s) no trajeto':''}</small></div><div class="address"><strong>${esc(t.destination)}</strong><small>Destino</small></div></div></div>`}
function overview(){const next=state.trips.filter(t=>['Agendada','Em andamento'].includes(t.status)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];const pending=state.trips.find(t=>t.status==='Orçamento');return `${header('Boa tarde, Djully.','Seu transporte organizado. Seu dia mais tranquilo.',false)}<div class="overview-grid"><section class="hero"><div class="hero-copy"><div class="eyebrow">A IVO vai com você</div><h2>O próximo destino<br>começa por aqui.</h2><p>Pessoas ou equipamentos. Conte com a gente para cuidar do caminho.</p><a href="#solicitar" class="btn">Solicitar transporte ${icon('arrow',16)}</a></div>${art()}</section><section class="balance-card" aria-label="Resumo da carteira"><div class="between"><span class="eyebrow">Sua carteira empresarial</span>${icon('wallet',18)}</div><div class="balance-main"><small>R$</small> ${available().toLocaleString('pt-BR',{minimumFractionDigits:2})}</div><div class="available-note">${icon('shield',11)} Disponível para novas viagens</div><div class="balance-split"><div><span>Reservado</span><strong>${money(reserved())}</strong></div><div><span>Gasto em outubro</span><strong>${money(state.spent)}</strong></div></div><a href="#carteira" class="text-link between">Ver carteira e extrato ${icon('arrow',14)}</a></section></div><div class="stats-row"><div class="mini-stat"><div class="stat-icon">${icon('calendar')}</div><div><strong>${state.trips.filter(t=>t.status==='Agendada').length.toString().padStart(2,'0')}</strong><span>Viagens agendadas</span></div></div><div class="mini-stat"><div class="stat-icon">${icon('file')}</div><div><strong>${state.trips.filter(t=>t.status==='Orçamento').length.toString().padStart(2,'0')}</strong><span>Orçamentos para aprovar</span></div></div><div class="mini-stat"><div class="stat-icon">${icon('check')}</div><div><strong>${state.trips.filter(t=>t.status==='Concluída').length.toString().padStart(2,'0')}</strong><span>Viagens concluídas</span></div></div></div><div class="workspace-grid"><section><div class="section-head between"><div><h2>Sua próxima viagem</h2><p class="muted">Tudo o que você precisa, antes de sair.</p></div><a href="#agenda" class="text-link">Ver agenda ${icon('arrow',13)}</a></div>${next?`<article class="next-trip"><div class="trip-top"><div class="trip-date">${dateSquare(next.date)}<div><h3>${weekday(next.date)}, ${next.time}</h3><p>${categories[next.category].name} · ${next.category==='passageiros'?next.people+' pessoas':next.weight+' kg'}</p></div></div>${badge(next.status)}</div>${routeBlock(next)}<div class="trip-foot"><div class="row"><div class="driver-dot">IB</div><span>Ivo Barbosa <span class="muted">· Motorista</span></span></div><button class="text-link" data-detail="${next.id}">Ver detalhes ${icon('arrow',13)}</button></div></article>`:empty('Nenhuma viagem agendada','Sua próxima viagem aparece aqui após aprovar um orçamento.','Solicitar transporte','solicitar')}</section><section><div class="section-head"><h2>${pending?'Uma decisão, e seguimos.':'Seus lugares de sempre'}</h2><p class="muted">${pending?'Um orçamento está esperando por você.':'Menos digitação na próxima solicitação.'}</p></div>${pending?`<article class="quote-card"><div class="eyebrow">${icon('clock',13)} Orçamento ${idLabel(pending.id)}</div><h3>${esc(pending.origin)} → ${esc(pending.destination)}</h3><p>${dateLabel(pending.date)}, ${pending.time} · ${categories[pending.category].name}</p><div class="between"><strong>${money(pending.price)}</strong><button class="btn" data-detail="${pending.id}">Revisar orçamento ${icon('arrow',13)}</button></div></article>`:''}<div class="saved-shortcuts">${state.places.slice(1,3).map(p=>`<button data-destination="${p.id}">${icon(p.icon,17)}<span>${esc(p.name)}<small>${esc(p.address)}</small></span><span class="chev">${icon('chevron',13)}</span></button>`).join('')}</div></section></div><section class="recent"><div class="section-head between"><h2>Últimas corridas</h2><a href="#corridas" class="text-link">Ver todas ${icon('arrow',13)}</a></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Trajeto</th><th>Data</th><th>Situação</th><th class="money">Valor</th></tr></thead><tbody>${[...state.trips].sort((a,b)=>b.id-a.id).slice(0,4).map(t=>`<tr class="click-row" data-detail="${t.id}" tabindex="0" role="button" aria-label="Abrir pedido ${idLabel(t.id)}"><td class="muted">${idLabel(t.id)}</td><td><strong>${esc(t.origin)}</strong><small>→ ${esc(t.destination)}</small></td><td>${dateLabel(t.date)}<small>${t.time}</small></td><td>${badge(t.status)}</td><td class="money">${t.status==='Cancelada'?money(t.fee||0):money(t.price)}<small>${t.status==='Cancelada'?'Cobrado':t.status==='Concluída'?'Cobrado':t.status==='Agendada'?'Reservado':'Orçado'}</small></td></tr>`).join('')}</tbody></table></div></section>`}
function empty(title,text,label,target){return `<div class="empty">${icon('route',30)}<h3>${title}</h3><p>${text}</p>${label?`<a class="btn compact" href="#${target}">${label}</a>`:''}</div>`}
function tripsPage(){return `${header('Minhas corridas','Do primeiro pedido à chegada. Acompanhe cada etapa.')}<div class="toolbar"><div class="tabs" role="group" aria-label="Filtrar corridas"><i class="tab-marker" aria-hidden="true"></i>${['Todos','Em aberto','Agendadas','Encerradas'].map(f=>`<button class="tab ${tripFilter===f?'active':''}" aria-pressed="${tripFilter===f}" data-filter="${f}">${f}</button>`).join('')}</div><label class="searchbox">${icon('search',16)}<input id="trip-search" aria-label="Buscar pedido ou local" placeholder="Buscar pedido ou local" value="${esc(query)}"></label></div><div id="trip-results">${tripResults()}</div>`}
function tripResults(){const list=state.trips.filter(t=>tripFilter==='Todos'||tripFilter==='Em aberto'&&['Solicitada','Orçamento','Em andamento'].includes(t.status)||tripFilter==='Agendadas'&&t.status==='Agendada'||tripFilter==='Encerradas'&&['Concluída','Cancelada'].includes(t.status)).filter(t=>[t.origin,t.destination,t.id,t.cost].join(' ').toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.id-a.id);return list.length?`<div class="trip-list">${list.map(t=>`<button class="trip-list-item" data-detail="${t.id}">${dateSquare(t.date)}<div class="trip-summary"><div class="item-meta"><span>${idLabel(t.id)}</span><span>·</span><span>${dateLabel(t.date)}, ${t.time}</span><span>·</span><span>${categories[t.category].name}</span></div><h3>${esc(t.origin)} → ${esc(t.destination)}</h3><p>${t.cost?esc(t.cost):'Sem centro de custo'}${t.status==='Cancelada'?' · '+(t.fee?'Cancelada com multa':'Cancelada sem cobrança'):''}</p></div><div class="item-right">${badge(t.status)}<span class="price">${t.status==='Solicitada'?'A orçar':money(t.status==='Cancelada'?(t.fee||0):t.price)}</span></div></button>`).join('')}</div>`:empty('Nenhuma corrida por aqui','Tente outro filtro ou solicite seu próximo transporte.','Nova solicitação','solicitar')}
function estimate(){const c=categories[draft.category];const km=18.6+draft.stops.filter(x=>x.trim()).length*4.2;const subtotal=c.base+km*c.km;return {km,subtotal,stops:draft.stops.filter(x=>x.trim()).length*15,total:Math.round((subtotal+draft.stops.filter(x=>x.trim()).length*15)*100)/100}}
function estimateHtml(){const e=estimate();return `<div class="between"><span class="eyebrow muted">Estimativa da viagem</span>${icon('file',16)}</div><div class="estimate-total" style="margin-top:12px">${money(e.total)}</div><p class="estimate-note">Referência demonstrativa. O valor fechado depende da aprovação do orçamento.</p><div class="line-item"><span>Tarifa base</span><span>${money(categories[draft.category].base)}</span></div><div class="line-item"><span>${e.km.toLocaleString('pt-BR')} km × ${money(categories[draft.category].km)}</span><span>${money(e.km*categories[draft.category].km)}</span></div>${e.stops?`<div class="line-item"><span>Paradas</span><span>${money(e.stops)}</span></div>`:''}<div class="line-item summary-total"><strong>Total estimado</strong><strong style="color:var(--ink)">${money(e.total)}</strong></div><button class="btn wide" form="booking-form" type="submit">Revisar solicitação ${icon('arrow',15)}</button><p class="estimate-note" style="text-align:center;margin-bottom:0">Nenhum valor é reservado nesta etapa.</p>`}
function rideMap(){return `<div class="ride-map" role="region" aria-label="Mapa ilustrativo da região de Itajaí"><div class="map-canvas" style="--map-zoom:${mapZoom}"><svg viewBox="0 0 1000 900" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><pattern id="blocks" width="110" height="95" patternTransform="rotate(-21)" patternUnits="userSpaceOnUse"><rect width="110" height="95" fill="#e9eae4"/><rect x="8" y="8" width="91" height="76" rx="5" fill="#e1e3dc"/><path d="M0 0H110M0 0V95" stroke="#fafbf8" stroke-width="13"/><path d="M56 7V86M7 48H103" stroke="#f4f5ef" stroke-width="4"/></pattern><filter id="map-shadow"><feDropShadow dx="0" dy="3" stdDeviation="5" flood-opacity=".12"/></filter></defs><rect width="1000" height="900" fill="url(#blocks)"/><path d="M80 0h165l-20 180-115 45-70-95Z M70 540l95-35 80 150-80 100-100-10Z M790 160l170-30 40 145-100 55-90-70Z" fill="#cad8bd"/><path d="M1030 80C870 210 985 380 890 470S758 540 810 730L1000 950H1100Z" fill="#c4dce0"/><path d="M-60 365C120 285 230 445 390 369S610 263 695 343 790 531 925 452" fill="none" stroke="#b9d4da" stroke-width="95"/><path d="M-60 365C120 285 230 445 390 369S610 263 695 343 790 531 925 452" fill="none" stroke="#c4dce0" stroke-width="82"/><g stroke="#fffef7" fill="none" stroke-linecap="round"><path d="M160-40 302 270 475 590 645 950" stroke-width="21"/><path d="M20 700 970 120M-30 860 930 610" stroke-width="18"/><path d="M-60 150 680 50 830 250" stroke-width="19"/><path d="M420-20 570 260 630 415 755 660 820 950" stroke-width="20"/></g><g stroke="#d8cfba" fill="none" stroke-width="2"><path d="M160-40 302 270 475 590 645 950M20 700 970 120M-30 860 930 610M-60 150 680 50 830 250M420-20 570 260 630 415 755 660 820 950"/></g><path d="m306 294 40 78m245-65 41 85" stroke="#f4f4ec" stroke-width="26"/><g fill="#738178" font-family="DM Sans,sans-serif" font-size="13" text-anchor="middle"><text x="565" y="185" font-size="23" letter-spacing="5" fill="#6b7d74">NAVEGANTES</text><text x="476" y="700" font-size="25" letter-spacing="6" fill="#6b7d74">ITAJAÍ</text><text x="620" y="840" font-size="12" letter-spacing="2">FAZENDA</text><text x="212" y="565" font-size="12" letter-spacing="2">SÃO VICENTE</text><text x="317" y="451" fill="#718e98" transform="rotate(-14 317 451)">Rio Itajaí-Açu</text><text x="528" y="525" font-size="11" transform="rotate(-31 528 525)">Av. Sete de Setembro</text><text x="98" y="675" fill="#7d9272" font-size="11">Área verde</text></g><g fill="#b4bbb0"><rect x="704" y="425" width="23" height="46" rx="3" transform="rotate(-25 704 425)"/><rect x="735" y="410" width="23" height="46" rx="3" transform="rotate(-25 735 410)"/><rect x="765" y="395" width="23" height="46" rx="3" transform="rotate(-25 765 395)"/></g><g class="map-route" style="opacity:${draft.origin.trim()&&draft.destination.trim()?1:0}"><path d="M425 625 476 590 346 350 302 270 620 215" fill="none" stroke="#fff" stroke-width="12" stroke-linejoin="round"/><path d="M425 625 476 590 346 350 302 270 620 215" fill="none" stroke="#173c4b" stroke-width="6" stroke-linejoin="round"/><circle cx="425" cy="625" r="10" fill="#173c4b" stroke="#fff" stroke-width="5"/><circle cx="620" cy="215" r="12" fill="#eb6028" stroke="#fff" stroke-width="5"/></g><g filter="url(#map-shadow)"><rect x="512" y="244" width="192" height="38" rx="19" fill="white"/><text x="608" y="268" text-anchor="middle" font-family="DM Sans,sans-serif" font-size="12" fill="#324d56">✈ Aeroporto de Navegantes</text><rect x="653" y="486" width="140" height="38" rx="19" fill="white"/><text x="723" y="510" text-anchor="middle" font-family="DM Sans,sans-serif" font-size="12" fill="#324d56">⚓ Porto de Itajaí</text><rect x="335" y="651" width="177" height="38" rx="19" fill="white"/><text x="423" y="675" text-anchor="middle" font-family="DM Sans,sans-serif" font-size="12" fill="#324d56">Escritório Umi San</text></g><g transform="translate(545 550) rotate(-30)"><rect x="-10" y="-20" width="20" height="40" rx="7" fill="#f9faf6" stroke="#9caaa5" stroke-width="2"/><rect x="-7" y="-11" width="14" height="16" rx="3" fill="#405e69"/></g></svg></div><div class="map-location">${icon('pin',15)} Itajaí e região <span>SC</span></div><div class="map-controls"><button class="icon-btn" data-map="in" aria-label="Ampliar mapa">${icon('plus')}</button><button class="icon-btn" data-map="out" aria-label="Reduzir mapa">−</button><button class="icon-btn" data-map="reset" aria-label="Restaurar enquadramento">${icon('refresh',17)}</button></div><div class="map-disclaimer">Mapa ilustrativo · sem localização ou rota real</div></div>`}
function booking(){return `<div class="ride-workspace step-${bookingStep}">${rideMap()}<section class="ride-sheet" aria-label="Solicitar viagem"><div class="sheet-grip" aria-hidden="true"></div><form id="booking-form" novalidate><div class="ride-intro"><div class="between"><span class="eyebrow muted">${bookingStep===1?'Seu próximo destino':'Detalhes da viagem'}</span><span class="step-caption">${bookingStep} de 2</span></div><h1>${bookingStep===1?'Para onde vamos?':'Como vamos?'}</h1><p>${bookingStep===1?'Pessoas ou equipamentos. A IVO vai com você.':'Escolha o transporte e programe sua saída.'}</p></div><div class="ride-step ${bookingStep===1?'':'hidden'}"><div class="route-fields"><label class="field">Origem<input required maxlength="180" name="origin" placeholder="De onde vamos sair?" value="${esc(draft.origin)}" list="saved-places" autocomplete="off"></label>${draft.stops.map((s,i)=>`<div class="stop-row"><label class="field">Parada ${i+1}<input name="stop-${i}" maxlength="180" value="${esc(s)}" placeholder="Onde vamos parar?" list="saved-places"></label><button type="button" class="icon-btn" data-remove-stop="${i}" aria-label="Remover parada ${i+1}">${icon('close',14)}</button></div>`).join('')}<label class="field">Destino<input required maxlength="180" name="destination" placeholder="Para onde vamos?" value="${esc(draft.destination)}" list="saved-places" autocomplete="off"></label></div><datalist id="saved-places">${state.places.map(p=>`<option value="${esc(p.name)}">${esc(p.address)}</option>`).join('')}</datalist><div class="between route-tools"><button class="text-link" type="button" data-action="add-stop" ${draft.stops.length>=3?'disabled':''}>${icon('plus',14)} Adicionar parada</button><span>${icon('calendar',13)} Viagem agendada</span></div><div class="ride-favorites"><div class="between"><h2>Seus lugares</h2><a href="#locais" class="text-link">Gerenciar ${icon('chevron',12)}</a></div>${state.places.slice(0,3).map(p=>`<button type="button" data-quick-place="${p.id}"><span class="favorite-icon">${icon(p.icon,18)}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.address)}</small></span>${icon('chevron',14)}</button>`).join('')}</div></div><div class="ride-step ${bookingStep===2?'':'hidden'}"><button type="button" class="ride-route-summary" data-action="route-back">${icon('back',17)}<span><strong>${esc(draft.origin)}</strong><small>→ ${esc(draft.destination)}</small></span><span class="text-link">Editar</span></button><div class="category-grid" role="group" aria-label="Categoria do transporte">${Object.entries(categories).map(([id,c])=>`<label class="category"><input type="radio" name="category" value="${id}" ${draft.category===id?'checked':''}><span class="category-inner">${vehicle(id)}<strong>${c.name}</strong><small>${c.capacity}</small></span></label>`).join('')}</div><div id="category-fields" style="margin-top:18px">${categoryFields()}</div><section class="ride-schedule"><h2>Quando vamos?</h2><div class="form-grid"><label class="field">Data da viagem<input name="date" type="date" min="${BASE_DATE}" required value="${draft.date}"></label><label class="field">Horário de saída<input name="time" type="time" required value="${draft.time}"></label></div></section><details class="ride-details"><summary>Adicionar detalhes <span>Opcional</span></summary><div class="form-grid"><label class="field">Centro de custo<input name="cost" maxlength="60" value="${esc(draft.cost)}" placeholder="Ex.: Operações"></label><label class="field">Contato no local<input name="contact" maxlength="80" value="${esc(draft.contact)}" placeholder="Nome do responsável"></label><label class="field full">Observações<textarea name="note" maxlength="500" placeholder="Bagagens, acesso ao local ou algo que devemos saber">${esc(draft.note)}</textarea></label></div></details></div><div id="booking-error" role="alert"></div><div class="ride-submit">${bookingStep===1?`<button class="btn navy wide" type="submit">Continuar ${icon('arrow',17)}</button><p>Você revisa tudo antes de enviar.</p>`:`<div class="ride-price"><div><small>Estimativa demonstrativa</small><strong id="ride-total">${money(estimate().total)}</strong></div><button type="button" class="text-link" data-action="estimate-info">Ver cálculo ${icon('info',14)}</button></div><button class="btn wide" type="submit">Revisar solicitação ${icon('arrow',17)}</button><p>O saldo só é reservado após aprovar o orçamento.</p>`}</div></form></section><a href="#carteira" class="map-balance">${icon('wallet',18)}<span>Disponível <strong>${money(available())}</strong></span>${icon('chevron',13)}</a></div>`}
function categoryFields(){return draft.category==='passageiros'?`<div class="form-grid"><div class="field"><label id="people-label">Número de passageiros</label><div class="stepper" role="group" aria-labelledby="people-label"><button type="button" data-people="-1" aria-label="Diminuir passageiros" ${draft.people<=1?'disabled':''}>−</button><output aria-live="polite">${draft.people}</output><button type="button" data-people="1" aria-label="Aumentar passageiros" ${draft.people>=4?'disabled':''}>+</button></div></div><p class="muted small" style="align-self:end;padding-bottom:7px">Até 4 passageiros.<br>Informe as bagagens nas observações.</p></div>`:`<div class="form-grid"><label class="field">Peso estimado (kg)<input name="weight" type="number" min="1" max="${categories[draft.category].max}" value="${esc(draft.weight)}" placeholder="Ex.: 120" required><small>Capacidade máxima: ${categories[draft.category].max.toLocaleString('pt-BR')} kg</small></label><label class="field">Descrição da carga<input name="cargo" maxlength="200" value="${esc(draft.cargo)}" placeholder="Ex.: ferramentas embaladas" required></label></div>`}
function calendar(){const days=new Date(calYear,calMonth+1,0).getDate(),start=new Date(calYear,calMonth,1).getDay();const monthName=new Date(calYear,calMonth,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});const list=state.trips.filter(t=>t.date===selectedDate).sort((a,b)=>a.time.localeCompare(b.time));return `${header('Sua agenda, sem desencontros.','Viagens, solicitações e histórico no mesmo calendário.')}<div class="calendar-layout"><section class="panel"><div class="between"><h2 style="margin:0;text-transform:capitalize">${monthName}</h2><div class="calendar-nav"><button class="icon-btn" data-month="-1" aria-label="Mês anterior">${icon('back',14)}</button><button class="btn secondary compact" data-action="today">Hoje</button><button class="icon-btn" data-month="1" aria-label="Próximo mês">${icon('arrow',14)}</button></div></div><div class="calendar-grid">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(x=>`<span class="day-label">${x}</span>`).join('')}${'<span></span>'.repeat(start)}${Array.from({length:days},(_,i)=>{const date=`${calYear}-${String(calMonth+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,count=state.trips.filter(t=>t.date===date).length;return `<button class="day ${date===selectedDate?'selected':''} ${date===BASE_DATE?'today':''}" data-day="${date}" aria-pressed="${date===selectedDate}" aria-label="${longDate(date)}, ${count} pedido(s)"><span>${i+1}</span>${count?`<div class="dots">${'<i></i>'.repeat(Math.min(count,3))}</div>`:''}</button>`}).join('')}</div><div class="credit-strip"><span style="height:5px;width:5px;background:var(--orange);border-radius:50%"></span> Dia com pedido · todos os estados incluídos</div></section><section class="calendar-list"><h2 style="text-transform:capitalize">${longDate(selectedDate)}</h2><p class="muted small">${list.length?list.length+' pedido(s) neste dia':'Seu dia está livre por aqui.'}</p>${list.map(t=>`<button class="agenda-item" data-detail="${t.id}"><div class="between"><strong>${t.time}</strong>${badge(t.status)}</div><h3>${esc(t.origin)} → ${esc(t.destination)}</h3><p>${idLabel(t.id)} · ${categories[t.category].name}</p></button>`).join('')}<button class="btn secondary" data-action="book-day">${icon('plus',15)} Solicitar para este dia</button></section></div>`}
function wallet(){return `${header('Clareza em cada movimento.','Seu saldo, suas reservas e o histórico da empresa.',false)}<div class="wallet-hero"><section class="wallet-main"><div class="between"><span class="eyebrow">Disponível para novas viagens</span>${icon('wallet',22)}</div><div class="balance-main">${money(available())}</div><p>O valor reservado já está descontado do disponível.</p><div class="balance-split"><div><span>Reservado</span><strong>${money(reserved())}</strong></div><div><span>Saldo contábil</span><strong>${money(accounting())}</strong></div><div><span>Limite adicional</span><strong>R$ 0,00</strong></div></div></section><section class="wallet-help">${icon('shield',24)}<h3>Planeje sem interromper o caminho.</h3><p>Consulte como funciona o crédito da empresa e a reserva de cada viagem.</p><button class="btn secondary compact" data-action="wallet-info">Entender minha carteira ${icon('arrow',14)}</button></section></div><div class="section-head between"><h2>Movimentações</h2><button class="btn secondary compact" data-action="export">${icon('download',14)} Exportar CSV</button></div><div class="toolbar"><div class="tabs" role="group" aria-label="Tipo de movimentação">${['Todos','Recarga','Reserva','Débito','Liberação','Multa'].map(f=>`<button class="tab ${f===ledgerFilter?'active':''}" aria-pressed="${f===ledgerFilter}" data-ledger="${f}">${f}</button>`).join('')}</div><span id="ledger-count" class="small muted" style="align-self:center">${state.ledger.filter(l=>ledgerFilter==='Todos'||l.kind===ledgerFilter).length} movimentações · demonstração</span></div><div id="ledger-results">${ledgerTable()}</div>`}
function ledgerTable(){const rows=state.ledger.filter(l=>ledgerFilter==='Todos'||l.kind===ledgerFilter).slice().reverse();return rows.length?`<div class="table-wrap wallet-table"><table><thead><tr><th>Data</th><th>Movimentação</th><th>Pedido</th><th class="money">Valor</th></tr></thead><tbody>${rows.map(l=>`<tr><td>${dateLabel(l.date)}</td><td><strong>${esc(l.description)}</strong><small>${l.kind}${l.kind==='Reserva'||l.kind==='Liberação'?' · altera o disponível, não o saldo contábil':''}</small></td><td>${l.trip?`<button class="text-link" data-detail="${l.trip}">${idLabel(l.trip)}</button>`:'—'}</td><td class="money transaction ${l.amount>0?'plus':''}">${l.amount>0?'+ ':''}${money(l.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma movimentação deste tipo','As movimentações da demonstração aparecem aqui.')}
function places(){return `${header('Os seus lugares de sempre.','Salve os endereços mais usados e encurte o próximo pedido.',false)}<div class="section-head between"><p class="muted small">${state.places.length} locais salvos neste navegador</p><button class="btn" data-action="new-place">${icon('plus',15)} Salvar local</button></div><div class="places-grid">${state.places.map(p=>`<article class="place-card"><div class="between"><div class="place-icon">${icon(p.icon,21)}</div><button class="icon-btn" aria-label="Remover ${esc(p.name)}" data-delete-place="${p.id}">${icon('trash',14)}</button></div><h3>${esc(p.name)}</h3><p>${esc(p.address)}</p><div class="between"><button class="text-link" data-destination="${p.id}">Usar como destino ${icon('arrow',14)}</button></div></article>`).join('')}</div>`}
function help(){return `${header('Uma pessoa do outro lado.','Respostas simples para seguir com tranquilidade.',false)}<div class="support-grid"><section class="panel"><h2>Como podemos ajudar?</h2>${[['Quando meu saldo é reservado?','Ao aprovar um orçamento, o valor passa de disponível para reservado. A solicitação inicial não movimenta a carteira.'],['Qual é a diferença entre estimativa e orçamento?','A estimativa é uma referência. O orçamento é o valor fechado que você revisa e aprova antes da viagem. Todos os preços e distâncias deste protótipo são fictícios.'],['Como funciona o cancelamento?','Antes de aprovar o orçamento, não há custo. Depois da aprovação, a simulação usa antecedência de 24 horas ou mais sem multa, entre 6 e 24 horas com 50%, e menos de 6 horas com 100%. O valor aparece antes de confirmar.'],['Posso solicitar transporte de equipamentos?','Sim. Selecione Carga leve ou Carga pesada e informe peso e descrição. Os limites apresentados são exemplos de interface, não disponibilidade real de frota.'],['Esses pedidos chegam ao motorista?','Não. Este é um protótipo independente. Pedidos, aprovações e movimentações ficam somente neste navegador. Nenhuma mensagem ou solicitação real é enviada.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><aside class="support-card">${icon('help',28)}<h2 style="margin-top:17px">Conte com a IVO.</h2><p>No produto final, este espaço conecta você à equipe de atendimento. Aqui, você pode explorar todas as telas sem realizar operações reais.</p><button class="btn navy" data-action="demo">Como testar ${icon('arrow',14)}</button><a class="btn ghost wide" href="#locais">Gerenciar locais salvos ${icon('pin',14)}</a></aside></div>`}
function content(){return ({inicio:overview,corridas:tripsPage,solicitar:booking,agenda:calendar,carteira:wallet,locais:places,ajuda:help}[page]||overview)()}
function syncNavigation(){document.querySelectorAll('.nav a,.bottom-nav a').forEach(a=>{const active=a.hash==='#'+page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});const active=$('.nav a.active'),marker=$('.nav-marker');if(active&&marker){marker.style.transform=`translateY(${active.offsetTop}px)`;marker.style.height=active.offsetHeight+'px';marker.style.opacity=1}else if(marker)marker.style.opacity=0;const crumb=$('.crumb strong');if(crumb)crumb.textContent=pageTitle();const count=$('.nav-badge');if(count)count.textContent=state.trips.filter(t=>['Solicitada','Orçamento','Agendada','Em andamento'].includes(t.status)).length}
function moveTabMarker(){document.querySelectorAll('.tabs').forEach(tabs=>{const active=tabs.querySelector('.tab.active');let marker=tabs.querySelector('.tab-marker');if(!marker){marker=document.createElement('i');marker.className='tab-marker';marker.setAttribute('aria-hidden','true');tabs.prepend(marker)}if(active){marker.style.width=active.offsetWidth+'px';marker.style.transform=`translateX(${active.offsetLeft-4}px)`}})}
function animateView(el,direction=1){if(!el||matchMedia('(prefers-reduced-motion: reduce)').matches)return;el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:.55,transform:`translateY(${direction*7}px)`},{opacity:1,transform:'translateY(0)'}],{duration:210,easing:'cubic-bezier(.2,.8,.2,1)'})}
function render(){const previous=page;page=location.hash.slice(1)||'solicitar';if(!['inicio','corridas','solicitar','agenda','carteira','locais','ajuda'].includes(page))page='solicitar';if(!$('#content'))$('#app').innerHTML=shell();else $('#content').innerHTML=content()+(page==='solicitar'?'':'<footer class="footer"><span>IVO Transportes · Cuidamos do caminho.</span><span>Ambiente de demonstração · dados fictícios</span></footer>');$('#content').classList.toggle('ride-main',page==='solicitar');document.body.classList.toggle('ride-mode',page==='solicitar');if(page==='solicitar')$('#content .footer')?.remove();document.title=`IVO · ${pageTitle()}`;syncNavigation();moveTabMarker();bindForms();if(previous!==page)animateView($('#content'));else if(page==='solicitar')animateView($('.ride-sheet'))}
function updateEstimate(){if($('#estimate'))$('#estimate').innerHTML=estimateHtml();if($('#ride-total'))$('#ride-total').textContent=money(estimate().total);const route=$('.map-route');if(route)route.style.opacity=draft.origin.trim()&&draft.destination.trim()?1:0}
function nextBookingStep(){readDraft();let message='',field='origin';if(draft.origin.trim().length<3)message='Informe o local de saída.';else if(draft.destination.trim().length<3){message='Informe o destino da viagem.';field='destination'}else if(draft.origin.trim().toLowerCase()===draft.destination.trim().toLowerCase()){message='Origem e destino precisam ser diferentes.';field='destination'}if(message){$('#booking-error').innerHTML=`<div class="error">${message}</div>`;fFocus(field);return}bookingStep=2;render();$('.ride-sheet').scrollTop=0;$('.ride-workspace').scrollTop=0;$('.ride-intro h1').setAttribute('tabindex','-1');$('.ride-intro h1').focus({preventScroll:true})}
function openModal(title,body,footer=''){lastFocus=document.activeElement;$('#modal').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Fechar janela">${icon('close',17)}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal()}
function closeModal(){if($('#modal').open)$('#modal').close();if(lastFocus?.isConnected)lastFocus.focus()}
function readDraft(){const f=$('#booking-form');if(!f)return;const data=new FormData(f);for(const k of ['origin','destination','date','time','cost','contact','note'])if(data.has(k))draft[k]=String(data.get(k));if(data.has('weight'))draft.weight=String(data.get('weight'));if(data.has('cargo'))draft.cargo=String(data.get('cargo'));draft.stops=draft.stops.map((s,i)=>String(data.get('stop-'+i)||''))}
function bindForms(){const f=$('#booking-form');if(f){f.addEventListener('input',()=>{readDraft();updateEstimate()});f.addEventListener('change',e=>{if(e.target.name==='category'){readDraft();draft.category=e.target.value;$('#category-fields').innerHTML=categoryFields();updateEstimate()}});f.addEventListener('submit',e=>{e.preventDefault();readDraft();if(bookingStep===1)nextBookingStep();else reviewBooking()})}$('#trip-search')?.addEventListener('input',e=>{query=e.target.value;$('#trip-results').innerHTML=tripResults()})}
function reviewBooking(){let err='',field='';if(draft.origin.trim().length<3){err='Informe uma origem com pelo menos 3 caracteres.';field='origin'}else if(draft.destination.trim().length<3){err='Informe um destino com pelo menos 3 caracteres.';field='destination'}else if(draft.origin.trim().toLowerCase()===draft.destination.trim().toLowerCase()){err='Origem e destino precisam ser diferentes.';field='destination'}else if(draft.category!=='passageiros'&&(!Number(draft.weight)||Number(draft.weight)>categories[draft.category].max||Number(draft.weight)<1)){err=`Informe um peso de 1 a ${categories[draft.category].max.toLocaleString('pt-BR')} kg.`;field='weight'}else if(draft.category!=='passageiros'&&draft.cargo.trim().length<3){err='Descreva a carga com pelo menos 3 caracteres.';field='cargo'}else if(!draft.date||draft.date<BASE_DATE){err='Escolha uma data a partir de 27/10/2026, a data de referência da demonstração.';field='date'}else if(!draft.time){err='Informe o horário de saída.';field='time'}else if(draft.date===BASE_DATE&&draft.time<'15:00'){err='Para hoje, escolha um horário após 15:00 (relógio simulado).';field='time'}if(err){$('#booking-error').innerHTML=`<div class="error">${err}</div>`;fFocus(field);return}$('#booking-error').innerHTML='';const e=estimate();openModal('Confira antes de enviar',`<p style="margin-bottom:22px">Tudo certo com os detalhes? O pedido ainda não reserva saldo.</p>${reviewInfo({...draft,price:e.total,status:'Solicitada'})}<hr class="divider"><div class="between"><span class="small muted">Estimativa demonstrativa</span><strong class="number" style="font-size:24px">${money(e.total)}</strong></div><div class="confirmation">${icon('info',15)}<span>Esta solicitação será salva apenas neste navegador. Nenhum transporte real será acionado.</span></div>`,`<button class="btn secondary" data-action="close">Voltar e editar</button><button class="btn" data-action="send-request">Enviar solicitação ${icon('arrow',14)}</button>`)}
function fFocus(name){const field=$('#booking-form').elements.namedItem(name);const details=field?.closest('details');if(details)details.open=true;field?.focus()}
function reviewInfo(t){return `<div class="review-grid"><div class="full"><div class="review-label">Trajeto</div><div class="review-value">${esc(t.origin)} ${icon('arrow',13)} ${esc(t.destination)}</div>${t.stops?.filter(Boolean).length?`<p class="small" style="margin-top:7px">Paradas: ${t.stops.filter(Boolean).map(esc).join(' · ')}</p>`:''}</div><div><div class="review-label">Data e horário</div><div class="review-value">${dateLabel(t.date)} · ${t.time}</div></div><div><div class="review-label">Categoria</div><div class="review-value">${categories[t.category].name}</div></div><div><div class="review-label">${t.category==='passageiros'?'Passageiros':'Carga'}</div><div class="review-value">${t.category==='passageiros'?t.people+' pessoa(s)':esc(t.weight)+' kg · '+esc(t.cargo)}</div></div><div><div class="review-label">Centro de custo</div><div class="review-value">${esc(t.cost||'Não informado')}</div></div><div><div class="review-label">Contato no local</div><div class="review-value">${esc(t.contact||'Não informado')}</div></div>${t.note?`<div class="full"><div class="review-label">Observações</div><div class="review-value">${esc(t.note)}</div></div>`:''}</div>`}
function showTrip(id){const t=state.trips.find(t=>t.id===Number(id));if(!t)return;modalTrip=t.id;const stages=['Solicitada','Orçamento','Agendada','Em andamento','Concluída'];const current=stages.indexOf(t.status);let foot='';if(t.status==='Orçamento')foot=`<button class="btn secondary" data-action="revision">Pedir revisão</button><button class="btn" data-action="approve">Aprovar ${money(t.price)} ${icon('check',14)}</button>`;else if(['Solicitada','Agendada'].includes(t.status))foot=`<button class="btn danger" data-action="cancel-trip">Cancelar pedido</button><button class="btn secondary" data-action="close">Fechar</button>`;else foot='<button class="btn secondary" data-action="close">Fechar</button>';openModal(`Pedido ${idLabel(t.id)}`,`<div class="detail-top">${badge(t.status)}<div style="text-align:right"><div class="price">${t.status==='Solicitada'?'A orçar':money(t.status==='Cancelada'?t.fee||0:t.price)}</div><div class="small muted">${t.status==='Cancelada'?'Cobrança efetiva':t.status==='Agendada'?'Valor reservado':t.status==='Concluída'||t.status==='Em andamento'?'Valor cobrado':t.status==='Orçamento'?'Orçamento demonstrativo':'Aguardando orçamento'}</div></div></div>${t.status==='Cancelada'?`<div class="confirmation">${t.fee?'Multa de '+money(t.fee)+' registrada na simulação.':'Cancelada sem cobrança. Nenhuma reserva permanece para este pedido.'}<br>Motivo: ${esc(t.reason||'Não informado')}</div>`:`<div class="timeline">${stages.map((s,i)=>`<div class="${i<current?'done':i===current?'current':''}">${s}</div>`).join('')}</div>`}${reviewInfo(t)}${t.status==='Orçamento'?`<div class="confirmation">Ao aprovar, ${money(t.price)} serão reservados. Disponível após aprovação: <strong>${money(available()-t.price)}</strong>.<br>Cancelamento: ≥24 h sem multa; de 6 a 24 h, 50%; menos de 6 h, 100%.</div>`:''}${t.revision?`<div class="form-tip">Revisão solicitada: ${esc(t.revision)}</div>`:''}${['Solicitada','Agendada','Em andamento'].includes(t.status)?`<div class="demo-action"><p>CONTROLE DE DEMONSTRAÇÃO · Avance a simulação para testar a próxima etapa. Não aciona o motorista.</p><button class="btn secondary compact" data-action="simulate">${icon('spark',13)} ${t.status==='Solicitada'?'Simular recebimento do orçamento':t.status==='Agendada'?'Simular início da viagem':'Simular conclusão da viagem'}</button></div>`:''}`,foot)}
function ledger(kind,amount,t,desc){state.ledger.push({id:`demo-${Date.now()}-${state.ledger.length}`,date:BASE_DATE,kind,amount,trip:t.id,description:desc})}
function cancelFee(t){if(t.status!=='Agendada')return 0;const h=(new Date(t.date+'T'+t.time)-new Date(BASE_DATE+'T15:00'))/3600000;return Math.round(t.price*(h>=24?0:h>=6?.5:1)*100)/100}
function demoInfo(){openModal('Explore a nova experiência',`<p>Este protótipo é independente do sistema IVO. Todos os dados são fictícios e ficam neste navegador.</p><hr class="divider"><div class="stack"><div><h3 style="margin-bottom:5px">1. Solicite um transporte</h3><p>Escolha o trajeto, categoria e horário. Revise os detalhes antes de enviar.</p></div><div><h3 style="margin-bottom:5px">2. Simule um orçamento</h3><p>Abra o pedido em Minhas corridas e use o controle de demonstração para receber um orçamento.</p></div><div><h3 style="margin-bottom:5px">3. Aprove e acompanhe</h3><p>Veja a reserva na carteira. Simule a saída e a conclusão para acompanhar as movimentações.</p></div></div><div class="form-tip">${icon('info',15)}<span>Relógio simulado: 27/10/2026 às 15:00. Distâncias, preços, capacidades e disponibilidade são exemplos para validar a interface.</span></div>`,`<button class="btn secondary" data-action="reset-confirm">Reiniciar demonstração</button><button class="btn navy" data-action="close">Entendi ${icon('check',14)}</button>`)}
function exportCSV(){const rows=state.ledger.filter(l=>ledgerFilter==='Todos'||l.kind===ledgerFilter);const cell=x=>'"'+String(x).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv='\uFEFF'+[['Data','Tipo','Descrição','Pedido','Valor'],...rows.map(l=>[l.date,l.kind,l.description,l.trip?idLabel(l.trip):'',l.amount.toFixed(2).replace('.',',')])].map(r=>r.map(cell).join(';')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=u;a.download='ivo-extrato-demonstracao.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Extrato de demonstração exportado.')}
async function action(name){const t=state.trips.find(t=>t.id===modalTrip);switch(name){case'route-back':readDraft();bookingStep=1;render();$('.ride-workspace').scrollTop=0;break;case'estimate-info':openModal('Como calculamos a estimativa',estimateHtml());$('#modal [type=submit]')?.remove();break;case'close':closeModal();break;case'help':navigate('ajuda');break;case'demo':demoInfo();break;case'notifications':openModal('O que precisa da sua atenção',state.trips.some(t=>t.status==='Orçamento')?state.trips.filter(t=>t.status==='Orçamento').map(t=>`<button class="trip-list-item" data-detail="${t.id}"><div><h3>Orçamento ${idLabel(t.id)} disponível</h3><p>${esc(t.origin)} → ${esc(t.destination)}</p><strong>${money(t.price)}</strong></div>${icon('arrow')}</button>`).join(''):'<p>Nenhum orçamento aguardando aprovação.</p>');break;case'add-stop':readDraft();if(draft.stops.length<3){draft.stops.push('');render();$('#booking-form').elements.namedItem('stop-'+(draft.stops.length-1)).focus()}break;case'send-request':{if(!$('#modal').open)return;const e=estimate();const trip={...structuredClone(draft),stops:draft.stops.filter(x=>x.trim()),id:state.seq++,status:'Solicitada',price:e.total,created:BASE_DATE};state.trips.unshift(trip);save();modalTrip=trip.id;closeModal();tripFilter='Todos';query='';navigate('corridas');openModal('Solicitação enviada',`<div class="success-view"><div class="confirm-icon">${icon('check',26)}</div><h3>Bom caminho, ${idLabel(trip.id)}.</h3><p>Seu pedido está salvo nesta demonstração. Você poderá revisar e aprovar o valor quando o orçamento chegar.</p><div class="confirmation">${esc(trip.origin)} → ${esc(trip.destination)}<br>${dateLabel(trip.date)} · ${trip.time} · ${categories[trip.category].name}</div><button class="btn navy" data-detail="${trip.id}">Acompanhar pedido ${icon('arrow',15)}</button></div>`);draft={...draft,origin:'',destination:'',note:'',cost:'',stops:[]};bookingStep=1;break}case'approve':if(t?.status!=='Orçamento')return;if(available()<t.price){toast('Saldo insuficiente para reservar esta viagem.');return}t.status='Agendada';ledger('Reserva',-t.price,t,'Valor reservado para a viagem');save();render();showTrip(t.id);toast('Orçamento aprovado. Valor reservado na carteira.');break;case'revision':if(t?.status!=='Orçamento')return;openModal('Pedir revisão do orçamento',`<p>Explique o que precisa mudar no pedido ${idLabel(t.id)}.</p><form id="revision-form" style="margin-top:20px"><label class="field">O que devemos revisar?<textarea name="reason" minlength="3" maxlength="500" required placeholder="Ex.: alterar o horário de saída"></textarea></label></form>`,`<button class="btn secondary" data-detail="${t.id}">Voltar</button><button type="submit" form="revision-form" class="btn">Solicitar revisão</button>`);$('#revision-form').onsubmit=e=>{e.preventDefault();t.revision=new FormData(e.target).get('reason');t.status='Solicitada';save();render();showTrip(t.id);toast('Revisão registrada na demonstração.')};break;case'cancel-trip':if(!t||!['Solicitada','Agendada'].includes(t.status))return;{const fee=cancelFee(t);openModal('Cancelar este pedido?',`<p>Pedido ${idLabel(t.id)} · ${dateLabel(t.date)}, ${t.time}</p><div class="confirmation">${fee?'Multa simulada: '+money(fee)+'. A reserva de '+money(t.price)+' será liberada e a multa debitada.':'Sem custo nesta etapa. '+(t.status==='Agendada'?'A reserva de '+money(t.price)+' será liberada.':'Nenhum valor foi reservado.')}</div><form id="cancel-form" style="margin-top:20px"><label class="field">Motivo do cancelamento<textarea name="reason" required minlength="3" maxlength="300" placeholder="Ex.: mudança no planejamento"></textarea></label></form>`,`<button class="btn secondary" data-detail="${t.id}">Manter pedido</button><button type="submit" form="cancel-form" class="btn danger">Confirmar cancelamento</button>`);$('#cancel-form').onsubmit=e=>{e.preventDefault();if(!['Solicitada','Agendada'].includes(t.status))return;if(t.status==='Agendada')ledger('Liberação',t.price,t,'Reserva liberada no cancelamento');if(fee){state.spent+=fee;ledger('Multa',-fee,t,'Multa simulada de cancelamento')}t.status='Cancelada';t.reason=new FormData(e.target).get('reason');t.fee=fee;save();render();showTrip(t.id);toast('Pedido cancelado na demonstração.')};break}case'simulate':if(!t)return;if(t.status==='Solicitada'){t.status='Orçamento';toast('Orçamento de demonstração recebido.')}else if(t.status==='Agendada'){ledger('Liberação',t.price,t,'Reserva convertida em cobrança');ledger('Débito',-t.price,t,'Cobrança no início da viagem');state.spent+=t.price;t.status='Em andamento';toast('Saída simulada. Débito registrado na carteira.')}else if(t.status==='Em andamento'){t.status='Concluída';toast('Viagem concluída na demonstração.')}else return;save();render();showTrip(t.id);break;case'today':calMonth=9;calYear=2026;selectedDate=BASE_DATE;render();break;case'book-day':draft.date=selectedDate<BASE_DATE?BASE_DATE:selectedDate;navigate('solicitar');break;case'wallet-info':openModal('Entenda sua carteira',`<div class="stack"><div><h3>Disponível · ${money(available())}</h3><p>Valor que pode ser usado para aprovar novos orçamentos.</p></div><div><h3>Reservado · ${money(reserved())}</h3><p>Comprometido com viagens aprovadas que ainda não começaram.</p></div><div><h3>Saldo contábil · ${money(accounting())}</h3><p>Créditos menos débitos. Inclui o saldo reservado. Ao iniciar uma viagem simulada, a reserva vira débito sem cobrança duplicada.</p></div><div><h3>Recargas</h3><p>No sistema real, a equipe da IVO confirma o crédito. Este protótipo não recebe pagamentos nem envia comprovantes.</p></div></div>`,`<button class="btn navy" data-action="close">Entendi</button>`);break;case'export':exportCSV();break;case'new-place':openModal('Um lugar para voltar',`<form id="place-form" class="stack"><label class="field">Nome do local<input name="name" required minlength="2" maxlength="60" placeholder="Ex.: Escritório central"></label><label class="field">Endereço ou referência<input name="address" required minlength="5" maxlength="180" placeholder="Rua, número, cidade"></label></form>`,`<button class="btn secondary" data-action="close">Cancelar</button><button class="btn" type="submit" form="place-form">Salvar local</button>`);$('#place-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);state.places.push({id:Date.now(),name:d.get('name').trim(),address:d.get('address').trim(),icon:'pin'});save();closeModal();render();toast('Local salvo neste navegador.')};break;case'reset-confirm':openModal('Recomeçar a demonstração?',`<p>Isso remove apenas os pedidos e locais criados neste protótipo e restaura os exemplos iniciais. O sistema real não é afetado.</p>`,`<button class="btn secondary" data-action="close">Manter meus testes</button><button class="btn danger" data-action="reset">Reiniciar demonstração</button>`);break;case'reset':state=structuredClone(seed);save();closeModal();render();toast('Exemplos iniciais restaurados.');break}}
document.addEventListener('click',e=>{const el=e.target.closest('button,a,[data-detail]');if(!el)return;if(el.dataset.map){mapZoom=el.dataset.map==='reset'?1:Math.max(.8,Math.min(1.8,mapZoom+(el.dataset.map==='in'?.2:-.2)));$('.map-canvas').style.setProperty('--map-zoom',mapZoom);return}if(el.dataset.quickPlace){readDraft();const place=state.places.find(p=>p.id===Number(el.dataset.quickPlace));if(place){draft.destination=place.name;if(!draft.origin&&state.places[0]?.id!==place.id)draft.origin=state.places[0]?.name||'';const f=$('#booking-form');f.elements.origin.value=draft.origin;f.elements.destination.value=draft.destination;updateEstimate();f.elements.destination.focus()}return}if(el.dataset.action){action(el.dataset.action);return}if(el.dataset.detail){showTrip(el.dataset.detail);return}if(el.dataset.filter){tripFilter=el.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===tripFilter);b.setAttribute('aria-pressed',b.dataset.filter===tripFilter)});moveTabMarker();$('#trip-results').innerHTML=tripResults();animateView($('#trip-results'));return}if(el.dataset.ledger){ledgerFilter=el.dataset.ledger;document.querySelectorAll('[data-ledger]').forEach(b=>{b.classList.toggle('active',b.dataset.ledger===ledgerFilter);b.setAttribute('aria-pressed',b.dataset.ledger===ledgerFilter)});moveTabMarker();$('#ledger-results').innerHTML=ledgerTable();$('#ledger-count').textContent=state.ledger.filter(l=>ledgerFilter==='Todos'||l.kind===ledgerFilter).length+' movimentações · demonstração';animateView($('#ledger-results'));return}if(el.dataset.destination){const p=state.places.find(x=>x.id===Number(el.dataset.destination));if(p){draft.destination=p.name;draft.origin=state.places[0]?.name===p.name?'':state.places[0]?.name||'';navigate('solicitar')}return}if(el.dataset.people){readDraft();draft.people=Math.max(1,Math.min(4,draft.people+Number(el.dataset.people)));$('#category-fields').innerHTML=categoryFields();return}if(el.dataset.removeStop!==undefined){readDraft();draft.stops.splice(Number(el.dataset.removeStop),1);render();return}if(el.dataset.month){calMonth+=Number(el.dataset.month);if(calMonth<0){calMonth=11;calYear--}if(calMonth>11){calMonth=0;calYear++}selectedDate=`${calYear}-${String(calMonth+1).padStart(2,'0')}-01`;render();return}if(el.dataset.day){selectedDate=el.dataset.day;render();return}if(el.dataset.deletePlace){const p=state.places.find(p=>p.id===Number(el.dataset.deletePlace));if(!p)return;openModal('Remover local salvo?',`<p>${esc(p.name)} será removido dos atalhos deste navegador. Seus pedidos anteriores serão mantidos.</p>`,`<button class="btn secondary" data-action="close">Manter</button><button class="btn danger" id="confirm-remove-place">Remover local</button>`);$('#confirm-remove-place').onclick=()=>{state.places=state.places.filter(x=>x.id!==p.id);save();closeModal();render();toast('Local removido.')};return}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-detail]')){e.preventDefault();showTrip(e.target.dataset.detail)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});window.addEventListener('resize',()=>{syncNavigation();moveTabMarker()});document.fonts.ready.then(()=>{syncNavigation();moveTabMarker()});render();
